{
  "criteria": [
    {
      "id": "A1",
      "quote": "consistent candidate snapshot with installed adapter apply; single publication only after complete candidate checked/closed/flushed; fail-safe precommit errors",
      "locator": "plans[0].final.work_items[W2].context",
      "grade": 2,
      "reason": "Private staging contains the adapter's committed prefixes, including runtime failures that prevalidation cannot prevent. Publication occurs only after the complete candidate is ready. Event 114 supports isolation under adapter error, replacement failure and prepublication kills. Postpublication termination exposes complete new state, never a prefix."
    },
    {
      "id": "A2",
      "quote": "success yields keep7,new3,old11; repeat same table; postcommit kill retains complete new with unknown acknowledgement, documented limitation.",
      "locator": "plans[0].final.work_items[W2].context",
      "grade": 2,
      "reason": "The plan snapshots existing inventory, preserves unrelated SKUs, publishes once and defines idempotent retry. Recovery treats abandoned candidates as inert and never automatically promotes them. Executed probes support complete publication and fresh-process replay. The commit-versus-acknowledgement boundary is explicit."
    },
    {
      "id": "A3",
      "quote": "OBSERVED: first row persists; remaining tail absent; outer transaction cannot undo adapter commits",
      "locator": "application_tool_evidence event 32",
      "grade": 2,
      "reason": "Exact adapter source was inspected in event 24. Event 32 executed invalid-middle and trigger-failure cases with fresh readback after outer rollback, plus successful replay preserving unrelated inventory. These observations preceded the initial plan. Later publication claims have executed evidence, and the failed first probe is not represented as a whole-script pass."
    },
    {
      "id": "A4",
      "quote": "All cases below are **planned**, owned by W2 after W1 helper readiness, due implement/test and retained for system-test/product-acceptance.",
      "locator": "planning_artifacts: docs/shiploop/environment.md, Harnesses and suites",
      "grade": 2,
      "reason": "Acceptance covers actual CLI success and replay, invalid middle records, adapter failures after a prefix, deterministic process interruption, replacement failure and fresh-process recovery. Independent complete-table assertions distinguish correct behavior from exit-code-only success. Baseline preservation is required, and probes or helper-only passes cannot substitute for product acceptance."
    },
    {
      "id": "A5",
      "quote": "helper definition/coverage guard aligned; seed unchanged; owned disposable DBs cleaned.",
      "locator": "application_tool_evidence event 160",
      "grade": 2,
      "reason": "The serial W1-to-W2 dependency is coherent: bounded process and database helpers precede their consuming checks. Remaining input-policy work has an owner. Work stays within local standard-library scope without unrelated infrastructure. Executed checks support seed preservation and disposal cleanup; child lifecycle handling is present in the probe source."
    }
  ],
  "false_readiness": [],
  "initial_unsupported_commitments": [],
  "decision_rework": [
    {
      "before": "Consistent SQLite snapshot plus same-directory replace can isolate adapter commits and publish full batch on supplied runtime; journal/sidecar constraints matter.",
      "after": "Candidate snapshot/installed adapter/same-directory replacement is feasible for clean DELETE-journal local regular files; active WAL main replacement is unsafe and must be rejected before effects.",
      "consequence": "Resolved an explicitly open feasibility gate and selected a concrete supported journal policy. Events 114 and 118 demonstrated safe candidate isolation and unsafe WAL main-file replacement. This materially informs implementation readiness; private staging and adapter retention were already in the initial plan.",
      "value": "valuable"
    },
    {
      "before": "permissions/schema/unrelated SKUs preserved; unsupported journal/path cases fail closed with honest diagnostics.",
      "after": "Reject symlinks/hardlinks via lexical lstat before resolve; cleanup from candidate creation covers backup errors; never report committed output failure as an uncommitted rollback.",
      "consequence": "Turns generic path and cleanup requirements into actionable implementation constraints, addressing normalization before alias checking and the probe's cleanup coverage beginning after backup. The postcommit acknowledgement distinction was already present initially.",
      "value": "valuable"
    }
  ],
  "unnecessary_investigation": [],
  "evidence_timing": [
    {
      "decision": "The adapter cannot provide atomic live-path batch application through a caller transaction.",
      "first_supported_at": "supplied",
      "basis": "Supplied src/adapter.py opens its own connection and calls db.commit() inside the row loop. Event 24 inspected that source during test-strategy."
    },
    {
      "decision": "Empirically characterize adapter prefix persistence and successful inventory replay.",
      "first_supported_at": "test-strategy",
      "basis": "Event 32 executed both partial-failure cases with reopened reads and successful repeated upserts preserving keep=7, before the producer seed_result."
    },
    {
      "decision": "Assign actual CLI, invalid-middle, interruption and recovery acceptance to implementation.",
      "first_supported_at": "test-strategy",
      "basis": "Event 39 authored concrete TC_1 through TC_8 procedures and independent inventory oracles, explicitly marked planned."
    },
    {
      "decision": "Build checked fixture/process helpers before the feature checks that consume them.",
      "first_supported_at": "plan-producer",
      "basis": "The initial seed_result already separates W1 helper production from W2 feature delivery and requires all TC_1 through TC_8. Later helper-location wording does not establish a new dependency."
    },
    {
      "decision": "Treat snapshot and replacement as feasible for clean DELETE-journal files, with recovery across the publication boundary.",
      "first_supported_at": "plan-improve",
      "basis": "Event 114 reached assertions for prefix and prereplace kills, postreplace completeness, adapter/replacement errors and fresh-process retry/replay before failing at the WAL negative-control observer."
    },
    {
      "decision": "Reject unsafe WAL publication without changing live journal mode.",
      "first_supported_at": "plan-improve",
      "basis": "Event 114 observed WAL preflight rejection and a malformed read after deliberately unsafe replacement. Event 118's targeted corrected observer confirmed both outcomes."
    }
  ],
  "summary": "The final plan fulfills all five planning obligations. Adapter hazards and meaningful acceptance coverage were established early; review added consequential publication evidence and a fail-closed WAL policy. The helper documentation alignment did not materially change the already-defined dependency or acceptance requirements. Product completion is not claimed.",
  "limitations": [
    "The CLI and new product tests remain unimplemented. Actual validation, path handling, permission/fsync faults and missing-database behavior still require W2 implementation acceptance.",
    "Publication observations cover the supplied local runtime and process interruption, not power loss or other platforms.",
    "The plan uses publication as the commit point. It does not establish literal old-state preservation for a command killed after publication but before success acknowledgement.",
    "The first publication probe exited 1. Its completed subcase assertions support bounded conclusions; the successful WAL-only rerun is not a successful rerun of the entire apparatus."
  ]
}
